record_types.code:
type aCanvas is record
    id          : aCanvasID := 0;
    pen         : aPenState;
    displayInfo : aDisplayInfoRec;
    bounds      : ARect := (0.0, 0.0, 100.0, 100.0);
    clipRect    : ARect := (0.0, 0.0, 100.0, 100.0);
    surface_ptr : SDL_Surface_Ptr;
    surface     : system.address;
    hardware_ptr: SDL_VideoInfo_Ptr;
    hardware    : system.address;
    name        : unbounded_string;
    kind        : aCanvasType := unknown;
    drawingType : aDrawingType := unknown;
    hasFont     : boolean := false;
    font_ptr     : TTF_font;
end record;

type AColourDefinition is record
  name : string(1..19);
  red, green, blue : ARGBComponent;
end record;

type ADisplayInfoRec is record
     TextBased : boolean;
     H_Res     : positive;
     V_Res     : positive;
     C_Res     : positive;
     P_Len     : natural;
     D_Buf     : natural;
end record;

type aPenState is record
    X            : ACoordinate;
    Y            : ACoordinate;
    Angle        : float;
    ErrorX       : ACoordinate;
    ErrorY       : ACoordinate;
    Mode         : aPenMode;
    Brush        : aPenBrush;
    Ink_R        : aRGBComponent;
    Ink_G        : aRGBComponent;
    Ink_B        : aRGBComponent;
    Pixel        : SDL_Generic_Pixel;
    pattern_ptr  : SDL_Surface_Ptr;
    pattern      : system.address;
    revealCount  : integer := 0;
end record;

type ARect is record
   left, top, right, bottom : ACoordinate;
end record;

